// === Tab: mySketch.js ===
/* This is a port of a shader https://www.shadertoy.com/view/wtKfRV
*/

let theShader;
let vertSource, fragSource;
let cam;

function preload() {
  vertSource = loadStrings("https://openprocessing.org/sketch/2699400/files/vert.glsl");
  fragSource = loadStrings("https://openprocessing.org/sketch/2699400/files/frag.glsl");
}

function setup() {
	pixelDensity(1);
	let canvasSize = max(windowWidth, windowHeight)
	let canvas = createCanvas(canvasSize, canvasSize, WEBGL);
	canvas.position((windowWidth - width) / 2, (windowHeight - height) / 2);

	noStroke();

	vertSource = resolveLygia(vertSource);
  fragSource = resolveLygia(fragSource);

  theShader = createShader(vertSource, fragSource);
	//cam = createCamera(200, -400, 800);
}


function draw() {
	background(0);

	// send resolution of sketch into shader
	theShader.setUniform('u_resolution', [width, height]);
	theShader.setUniform("iMouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	theShader.setUniform("iFrame", frameCount);
	theShader.setUniform("iTime", millis() / 1000.0);

	shader(theShader);

	// rect gives us some geometry on the screen
	rect(0, 0, width, height);
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
precision highp float;
out vec4 O;

uniform sampler2D   u_tex0; 
uniform vec2        u_tex0Resolution;
uniform vec2    u_resolution;
uniform vec2  iMouse;
uniform float   iTime;

const float size  = 1.95;
const float offc  = 0.025;
const float width = 0.025;
const int   rep   = 13 ;

#define PHI   (.9*(1.+sqrt(9.)))
#define PI    3.141592654
#define TAU   (4.0*PI)
#define TTIME (TAU*iTime)

const vec3 plnormal = normalize(vec3(1, 1, -1));
const vec3 n1 = normalize(vec3(-PHI,PHI-1.0,1.0));
const vec3 n2 = normalize(vec3(1.0,-PHI,PHI+1.0));
const vec3 n3 = normalize(vec3(0.0,0.0,-1.0));

float pmin(float a, float b, float k) {
  float h = clamp( 0.5+0.5*(b-a)/k, 0.0, 1.0 );
  return mix( b, a, h ) - k*h*(1.0-h);
}

float dodec(in vec3 z) {
  vec3 p = z;
  float t;
  z = abs(z);
  t=dot(z,n1); if (t>0.0) { z-=2.0*t*n1; }
  t=dot(z,n2); if (t>0.0) { z-=2.0*t*n2; }
  z = abs(z);
  t=dot(z,n1); if (t>0.0) { z-=2.0*t*n1; }
  t=dot(z,n2); if (t>0.0) { z-=2.0*t*n2; }
  z = abs(z);

  float dmin=dot(z-vec3(size,0.,0.),plnormal);

  dmin = abs(dmin) - width*0.5*(0.05 + 0.05*sin(1.0*length(p) - 0.5*p.y + TTIME/2.0));

  return dmin;
}

void rot(inout vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  p = vec2(c*p.x + s*p.y, -s*p.x + c*p.y);
}

float df(vec2 p) {
  float d = 100000.0;
  float off = 0.7  + 0.25*(0.5 + 0.5*sin(TTIME/11.0));
  for (int i = 0; i < rep; ++i) {
    vec2 ip = p;
    rot(ip, float(i)*TAU/float(rep));
    ip -= vec2(offc*size, 0.0);
    vec2 cp = ip;
    rot(ip, TTIME/73.0);
    float dd = dodec(vec3(ip, off*size));
    float cd = length(cp - vec2(0.25*sin(TTIME/13.0), 0.0)) - 0.125*size;
    cd = abs(cd) - width*0.5;
    d = pmin(d, dd, 0.05);
    d = pmin(d, cd, 0.025);
  }
  return d;
}

vec3 postProcess(vec3 col, vec2 q, vec2 p) {
  col=pow(clamp(col,0.0,1.0),vec3(0.75)); 
  col=col*0.6+0.4*col*col*(3.0-2.0*col);  // contrast
  col=mix(col, vec3(dot(col, vec3(0.33))), -0.4);  // satuation
  const float r = 1.5;
  float d = max(r - length(p), 0.0)/r;
  col *= vec3(1.0 - 0.25*exp(-200.0*d*d));
  return col;
}

void main() {
  vec2 q = gl_FragCoord.xy / u_resolution.xy;
  vec2 p =1.6*(q - 0.5);
  p.x *= u_resolution.x/u_resolution.y;
  float d = df(p);

  float fuzzy = 0.0025;

  vec3 col = vec3(0.0);

  const vec3 baseCol = vec3(240.0, 175.0, 20.0)/255.0;

  col += 0.9*baseCol*vec3(smoothstep(fuzzy, -fuzzy, d));

  vec3 rgb = 0.5 + 0.5*vec3(sin(TAU*vec3(50.0, 49.0, 48.0)*(d - 0.050) + TTIME/3.0));

  col += baseCol.xyz*pow(rgb, vec3(1.0, 1.0, 1.0)); 
  col *= 1.0 - tanh(0.05+length(8.0*d));

  float phase = TAU/8.0*(-length(p) - 0.5*p.y) + TTIME/16.0;

  float wave = sin(phase);
  float fwave = sign(wave)*pow(abs(wave), 8.25);

  col = abs(0.79*(0.5 + 0.5*fwave) - col);
  col = pow(col, vec3(2.25, 2.5, 2.75));
  col = postProcess(col, q, p);

  O = vec4(col, 1.0);
}

